  "content": "package com.skillforge.platform.security;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.util.Base64;

/**
 * Issues and verifies HS256-signed JWTs (username subject, role claim,
 * iat/exp in seconds) keyed by the jwt.secret *** Implemented directly
 * on javax.crypto so it is independent of the jjwt library version.
 */
@Component
public class JwtTokenProvider {

    private static final String HEADER =
            base64UrlEncode("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));

    private final byte[] secretKey;
    private final long expirationSeconds;
    private final ObjectMapper objectMapper = new ObjectMapper();

    public JwtTokenProvider(@Value("${jwt.secret}") String secret,
                            @Value("${jwt.expiration}") long expirationSeconds) {
        this.secretKey = secret.getBytes(StandardCharsets.UTF_8);
        this.expirationSeconds = expirationSeconds;
    }

    public String generateToken(String username, String role) {
        long issuedAt = System.currentTimeMillis() / 1000;
        ObjectNode payload = objectMapper.createObjectNode();
        payload.put("sub", username);
        payload.put("role", role);
        payload.put("iat", issuedAt);
        payload.put("exp", issuedAt + expirationSeconds);
        String signingInput = HEADER + "." + base64UrlEncode(payload.toString().getBytes(StandardCharsets.UTF_8));
        return signingInput + "." + base64UrlEncode(hmacSha256(signingInput));
    }

    public boolean validateToken(String token) {
        return parsePayload(token) != null;
    }

    public String getUsername(String token) {
        JsonNode payload = parsePayload(token);
        return payload == null ? null : payload.path("sub").asText(null);
    }

    public String getRole(String token) {
        JsonNode payload = parsePayload(token);
        return payload == null ? null : payload.path("role").asText(null);
    }

    private JsonNode parsePayload(String token) {
        if (token == null) {
            return null;
        }
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return null;
        }
        try {
            byte[] expectedSignature = hmacSha256(parts[0] + "." + parts[1]);
            byte[] providedSignature = Base64.getUrlDecoder().decode(parts[2]);
            if (!MessageDigest.isEqual(expectedSignature, providedSignature)) {
                return null;
            }
            JsonNode payload = objectMapper.readTree(Base64.getUrlDecoder().decode(parts[1]));
            JsonNode exp = payload.get("exp");
            if (exp == null || exp.asLong() * 1000 < System.currentTimeMillis()) {
                return null;
            }
            return payload;
        } catch (Exception e) {
            return null;
        }
    }

    private byte[] hmacSha256(String data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secretKey, "HmacSHA256"));
            return mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("Unable to compute JWT signature", e);
        }
    }

    private static String base64UrlEncode(byte[] bytes) {
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
    }
}
